import{_ as n,p as t,q as s,s as e,R as a,t as c,Y as o,n as d}from"./framework-e1bed10d.js";const h="/my-blog/assets/052_01-dd98bef6.png",p={},i=e("h1",{id:"核算系统改造的实战-glp-改造",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#核算系统改造的实战-glp-改造","aria-hidden":"true"},"#"),a(" 核算系统改造的实战：GLP 改造")],-1),l={href:"https://mp.weixin.qq.com/s?__biz=MzIzNzQ5NjU5NQ==&mid=2247485074&idx=1&sn=9b29f920e79a1a82bba657cdea60614b&chksm=e8c6f6eedfb17ff88ae8645d4c21f3f7ac8ef7aea72ec386d8ab51b90c93d9c2973a6587f682",target:"_blank",rel:"noopener noreferrer"},_=o('<hr><p>七、核算系统改造的实战：<strong>GLP 改造</strong></p><p><img src="'+h+'" alt="图片"></p><p><strong>图6-15 核算系统改造实战：GLP 改造路径</strong></p><h3 id="一-为什么要动核算系统" tabindex="-1"><a class="header-anchor" href="#一-为什么要动核算系统" aria-hidden="true">#</a> （一）为什么要动核算系统</h3><p>很多机构上线新业务（资产转让、联合贷）时，老核算系统撑不住：总分不平、表外账缺失、客户账对不上。我在互金平台做过一次核算系统改造，核心就三件事：把账对平、把表外补上、把客户账核上。</p><p>核算系统（GLP）拆成三大模块：核算账户管理（机构账、商户账、总账的开户、查询、编辑）、综合查询（总账查询、机构账查询、客户账查询、联机/批量会计分录查询、资金头寸查询、资产包管理、资产转让账查询）、调账（内部机构账调账，含录入、复核、审批全流程）。这套拆分的逻辑是：账户管理是“建账”，综合查询是“看账”，调账是“改账”，三个模块职责清晰，互不干扰。改造时也是按模块逐个推进：先把账户体系理清楚，再把查询做全，最后把调账流程规范起来。</p><h3 id="二-总分核对差异调整" tabindex="-1"><a class="header-anchor" href="#二-总分核对差异调整" aria-hidden="true">#</a> （二）总分核对差异调整</h3><p>第一件事是数据校验核查：总分核对（客户账与机构账余额），发现不一致，就查找差异金额，以客户账为依据调整机构账余额，确保每日总分核对一致、机构内借贷余额汇总一致。这是存量改造的第一步，账先平，才能谈别的。</p><h3 id="三-表外账务平衡检查" tabindex="-1"><a class="header-anchor" href="#三-表外账务平衡检查" aria-hidden="true">#</a> （三）表外账务平衡检查</h3><p>第二件事是表外账：按系统设计的会计分录，表外账务不允许存在单边账，所以要增加表外账务平衡性检查，特殊科目用白名单过滤。同时，转让后的借据要维护表外客户账，改造前核算系统没有维护转让后借据的客户账，转让后客户账被清0，导致无法查询借据状态、无法和核心对账。</p><h3 id="四-客户账核对" tabindex="-1"><a class="header-anchor" href="#四-客户账核对" aria-hidden="true">#</a> （四）客户账核对</h3><p>第三件事是账务核对：以借据为单位，和核心系统进行本息费余额、发生额的比对。日终核心出具每笔借据的本息费余额、发生额，核算系统依据客户账进行比对，表内核对、表外核对分开做，逐步把差异清零。</p><p>调账是核算系统里唯一允许“人工改账”的入口，流程必须严。GLP的调账走四状态机：未提交（操作员录入，可编辑可删除）→待复核（提交后等待复核）→已复核（复核通过，调账生效，余额实时更新）/拒绝（复核驳回，可修改后重新提交）。关键校验有三道：第一道是借贷平衡校验，提交复核时检查借方合计等于贷方合计，不平就报错；第二道是透支校验，如果科目配置为“不可透支”，调账后账户余额不能小于0，否则复核拒绝；第三道是权限隔离，录入和复核必须是不同的人，不能自己录自己批。调账生效后不可删除，只能再做一笔反向调账冲正，这和“账务不能删、只能冲”的纪律一致。</p><p>这三次改造的教训：核算系统出问题，九成是“账没记全”（表外漏记、客户账缺维护）和“对不上”（总分不平），而不是记账公式错。所以上新的核算功能，先过三关：账全不全、账平不平、能不能核。</p><p>调账流程上还有一个容易漏的点：审批角色必须分离。我们把调账分成申请、审批、执行、复核四个环节，每个环节都要人来确认，不能一个人从头做到尾；调账分录要记录原因、原分录号、调整前后的余额，事后审计要能追溯。这套流程看起来笨重，但在核算系统里，笨重就是安全。</p><p>GLP改造的核心难点不在技术，在数据迁移。旧系统跑了多年，里面有历史遗留的错误分录、手工调账的痕迹、科目映射的不一致，这些数据迁到新系统里，如果不清洗干净，新系统一上线就会带着旧账的错误跑。我们的做法是先做三个月的并行跑批：旧系统和新系统每天同时跑日终，把两边的科目余额逐笔比对，差异超过一分钱就要查原因。三个月下来，查出来的问题大大小小有两百多个，大部分是旧系统的历史遗留，小部分是新系统的配置错误。全部清零之后才敢切流。</p>',17);function f(b,m){const r=d("ExternalLinkIcon");return t(),s("div",null,[i,e("blockquote",null,[e("p",null,[a("公众号：侃西东　·　发布日期：2026-11-07　·　"),e("a",l,[a("微信原文"),c(r)])])]),_])}const x=n(p,[["render",f],["__file","052.html.vue"]]);export{x as default};
